/* =============================================================================
   SPD - Semilla de datos para Oracle (ambientes locales o de desarrollo)
   Generado desde la base PostgreSQL local de SPD (datos de prueba del repo).

   Orden: 1) siif_base_tables.sql  2) spd_schema.sql  3) spd_views.sql  4) seed/spd_seed_01.sql ... spd_seed_12.sql, en orden

   Notas
   - COMPANIA, ENTIDADES_PRY y PLAN_DESARROLLO se llenan solo con lo mínimo
     (no ejecutar esas secciones en el SIIF real, donde ya existen).
   - Se conservan los IDs de PostgreSQL. ENTIDADES_PRY.ID = entity.id y
     PLAN_DESARROLLO.ID = SPD_DEV_PLAN.ID = dev_plan.id.
   - Las FK que apuntan a la misma tabla se deshabilitan durante la carga.
   - Al final se reinician las columnas IDENTITY y las secuencias del SIIF.
   ============================================================================= */
SET DEFINE OFF
SET SQLBLANKLINES ON
SET FEEDBACK OFF
WHENEVER SQLERROR EXIT FAILURE ROLLBACK

ALTER TABLE SPD_PRODUCT_CATALOG DISABLE CONSTRAINT SPD_PROD_CAT_PARENT_FK;
ALTER TABLE SPD_DEV_PLAN_LEVEL  DISABLE CONSTRAINT SPD_DPL_PARENT_FK;
ALTER TABLE SPD_GOAL            DISABLE CONSTRAINT SPD_GOAL_PARENT_FK;


