  'Contempla las actividades asociadas al pago de nómina del personal docente, directivo docente  y administrativo de los establecimientos educativos, incluidos los gastos inherentes a la nómina como los aportes patronales y parafiscales. Así mismo, incluye la  prestación del servicio educativo a través de la contratación con privados y los servicios administrativos de apoyo a la prestación del servicio educativo tales como arrendamiento de bienes inmuebles, servicios de aseo y vigilancia, impresiones y publicaciones, primas por seguros para amparar personas y bienes de los establecimientos educativos, el desarrollo de las acciones requeridas para la adecuada disposición de los bienes y la mitigación del deterioro y el pago de servicios públicos domiciliarios y telefonía móvil e internet.',
