  381,
  'S',
  '2201051',
  'Infraestructura educativa construida',
  'Contempla la construcción de nueva infraestructura educativa a partir de: 1. La construcción de sedes nuevas en nuevos lotes: corresponde a la creación de una sede nueva con DANE nuevo en un nuevo lote, se caracteriza por ampliar la capacidad instalada para atender nuevos cupos escolares por demanda de servicio. 2. La construcción de nuevas sedes por restitución total o reubicación total de la sede existente: Corresponde a la construcción de nuevas sedes derivadas de procesos de restitución total en el mismo lote o reubicación total en lote nuevo, se caracteriza por ser construcciones completamente nuevas que garantizan capacidad instalada para jornada única o nueva matricula la mayoría derivada de condiciones de riesgo o vulnerabilidad. Estas sedes nuevas cubren ciclos educativos completos de manera integral y autónoma de acuerdo a los ambientes pedagógicos básicos y complementarios  definidos en la NTC 4595,  que permitan garantizar capacidad instalada y con ello implementar jornada ',
