  'Servicio de telecomunicaciones para el envío de alertas tempranas a la población.',
  'El Sistema Centralizado de Alertas Tempranas  está conformado por equipos (hardware y software), licenciamiento de uso de software, elementos y accesorios necesarios,  con el cual se podrá alertar a la población de una zona geográfica determinada de un posible evento de desastres, mediante el envío de mensajes sobre las redes de telefonía móvil, las emisoras de radiodifusión sonora, los canales de televisión, internet y cualquier otro medio de comunicación que se pueda incorporar a este sistema..',
