  545,
  'S',
  '2301043',
  'Servicio del código postal',
  'El Código Postal es una herramienta que asigna a distintas zonas o lugares del país un código, que junto con la dirección sirven para facilitar y mecanizar el encaminamiento de un objeto postal (una pieza de correo como una carta, un sobre, un paquete o cualquier elemento que necesite ser llevado a un lugar). No reemplaza la dirección, sino que la complementa para facilitar la entrega de un envío. El objetivo es lograr la inclusión del código postal en los envíos de documentos y pequeños paquetes que cursan a través de la red postal, por parte de las entidades territoriales y operadores postales. ',
  NULL,
  120,
